/* From Uiverse.io by AbanoubMagdy1 - Tags: switch */
/* The switch - the box around the slider */
.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 5.2em;
  height: 2em;
  overflow: hidden;
}

/* Hide default HTML checkbox */
.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

/* The slider */
.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #eee;
  transition: .4s;
  border-radius: 30px;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 20px;
  border: 1px solid #333;
  left: 0.4em;
  bottom: 0.2em;
  background-color: white;
  transition: .4s;
}

.__UIV_SCOPE__ input:checked + .slider {
  background-color: #2196F3;
}

.__UIV_SCOPE__ input:focus + .slider {
  box-shadow: 0 0 1px #2196F3;
}

.__UIV_SCOPE__ input:checked + .slider:before {
  transform: translateX(3em);
}

.__UIV_SCOPE__ .switch .text {
  position: absolute;
  top: 50%;
  pointer-events: none;
  text-transform: uppercase;
  transform: translateY(-50%);
  transition: .4s;
}

.__UIV_SCOPE__ .switch .text.on {
  left: .8rem;
  transform: translateX(-3rem) translateY(-50%);
}

.__UIV_SCOPE__ .switch .text.off {
  color: #999;
  right: .8rem;
}

.__UIV_SCOPE__ input:checked ~ .text.off {
  transform: translateX(3rem) translateY(-50%);
}

.__UIV_SCOPE__ input:checked ~ .text.on {
  transform: translateX(0) translateY(-50%);
}
